const wh    = $('Webhook').first().json;   // le MESSAGE, toujours
const fiche = $('Charger fiche').first().json || {};  // la FICHE, toujours

const body     = wh.body || {};
const messages = body.data?.messages || {};
const key      = messages.key || {};
const fromMe   = key.fromMe === true;
const texte    = (messages.messageBody || '').trim();
const estCommande = texte.startsWith('/');

// Une note arrive rarement nue. Le 16 aout, un client a repondu « '2 » : le
// test exact /^[1-5]$/ l'a rejete, le message est parti a l'assistante, et la
// note a ete perdue en silence. On tolere donc ce qui ENTOURE le chiffre —
// apostrophe, guillemets, etoiles, ponctuation, « /5 » — mais JAMAIS une
// lettre : « 2 pizzas » ou « 2 kg » doivent rester des phrases pour
// l'assistante.
function noteDe(txt) {
  const t = String(txt).normalize('NFKC').trim().replace(/\s*(?:\/|sur)\s*5\s*$/i, '');
  const m = t.match(/^[^\p{L}\p{N}]*([1-5])[^\p{L}\p{N}]*$/u);
  return m ? Number(m[1]) : null;
}

// Calcule ICI, une seule fois : « Note 1-5 ? » et « Aiguilleur note » relisent
// ce champ au lieu de refaire le test. Trois regex separees avaient fini par
// diverger, et c'est ainsi qu'un message pouvait etre une note d'un cote et
// une phrase de l'autre.
const note_detectee = noteDe(texte);

if (!texte) return [];
if (fromMe && !estCommande && note_detectee === null) return [];

const digits = String(key.cleanedSenderPn || '').replace(/\D/g, '');
const phone  = digits ? (digits.startsWith('225') ? digits : '225' + digits) : '';
const jid    = String(key.senderPn || (digits ? digits + '@s.whatsapp.net' : ''));
const prenom = String(body.data?.pushName || 'Client');

return [{ json: {
  canal: 'whatsapp', phone, jid, texte, prenom, note_detectee,
  timestamp: new Date().toISOString(),

  // La fiche marchand greffee : tout l'aval devient generique.
  // `slug` est la cle de tenant : il sert aux routes /api/boutiques/<slug>/...
  slug:              fiche.slug || String(wh.params?.slug || ''),
  boutique_id:       fiche.id || '',
  nom_boutique:      fiche.nom || '',
  // Le metier de la boutique : l'assistante y accorde son vocabulaire, pour
  // ne pas souhaiter bon appetit au client d'une boutique de vetements.
  secteur:           fiche.categorie || '',
  sheet_commandes:   fiche.sheet_commandes || '',
  sheet_menu:        fiche.sheet_menu || '',
  sheet_notes:       fiche.sheet_notes || '',
  groupe_livreurs:   fiche.groupe_livreurs || '',
  telegram_marchand: fiche.telegram_marchand || '',
  whatsapp_marchand: fiche.telephone || '',
  sheet_document_id: fiche.sheet_document_id || '',
}}];

const wa = $('Normalisateur WA').first().json;
const rows = $input.all().map(i => i.json);

// Au-dela de ce delai, un chiffre seul n'est plus une note : c'est un client
// qui repond « 2 » pour dire deux articles.
const FENETRE_H = 48;

// `heure_livraison` n'a pas de format garanti selon le noeud qui a ecrit la
// ligne. On reconnait l'ISO et le format ivoirien, dans cet ordre : laisser
// Date.parse voir « 07/08/2026 » lui ferait lire le 8 juillet.
function instant(v) {
  const s = String(v ?? '').trim();
  if (!s) return NaN;
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return Date.parse(s);
  const m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:[ T](\d{1,2}):(\d{2}))?/);
  if (!m) return NaN;
  const p = (n) => String(n ?? 0).padStart(2, '0');
  return Date.parse(`${m[3]}-${p(m[2])}-${p(m[1])}T${p(m[4])}:${m[5] ?? '00'}:00`);
}

let vers = 'cerveau';
let note = null;
let order_id = '';

// Le chiffre a deja ete reconnu, une seule fois, par « Normalisateur WA ».
// Ne pas refaire le test ici : c'est en le dupliquant qu'un « '2 » avait pu
// etre une note pour un noeud et une phrase pour le suivant.
const chiffre = wa.note_detectee;

if (chiffre !== null && chiffre !== undefined) {
  const maintenant = Date.now();

  const livrees = rows
    .filter((r) => {
      const st = String(r.statut_livraison || '').toLowerCase();
      return st.includes('livr') && !st.startsWith('en_');
    })
    .map((r) => ({ r, t: instant(r.heure_livraison) }))
    // Un horodatage illisible n'est pas une preuve d'anciennete : on le garde,
    // sinon un format inattendu ferait disparaitre toutes les notes d'un coup.
    .filter((x) => !Number.isFinite(x.t) || maintenant - x.t <= FENETRE_H * 3600 * 1000);

  if (livrees.length) {
    // Tri chronologique reel. L'ancien comparait des chaines : juste en ISO,
    // faux des que la date s'ecrit 13/08/2026 — le travers qui avait fait
    // ressortir une vieille commande pendant les tests.
    const cle = (x) => (Number.isFinite(x.t) ? x.t : 0);
    livrees.sort((a, b) => cle(b) - cle(a));
    vers = 'note';
    note = chiffre;
    order_id = String(livrees[0].r.order_id || '');
  }
}

return [{ json: {
  canal: wa.canal,
  phone: wa.phone,
  texte: wa.texte,
  prenom: wa.prenom,
  vers: vers,
  note: note,
  order_id: order_id
}}];

// Le gerant doit pouvoir RAPPELER le client, donc lire son nom et son numero.
//
// Ce noeud lisait `client_name` et `client_chat_id` : les colonnes de la
// FEUILLE, puisqu'il recevait jusqu'ici la ligne que « Enregistrer note »
// venait d'y ecrire. Ce miroir ayant quitte le chemin critique, l'entree est
// desormais la sortie de l'aiguilleur, qui nomme les memes choses `prenom` et
// `phone`. On accepte les deux : l'alerte doit survivre au cablage.
const j = $input.first().json;
const note = Number(j.note || 0);

// Pas d'alerte pour les bonnes notes.
if (note >= 4) return [];

const nom = j.prenom || j.client_name || 'Client';
const joindre = j.phone || j.client_chat_id || 'numero inconnu';

return [{ json: {
  message: `🚨 ALERTE MAUVAISE NOTE — ${nom} a noté ${note}/5 (commande ${j.order_id || ''}). Client à rappeler : ${joindre}`
}}];

